  constraints: ['1 <= n <= 200', '1 <= W <= 5000', '1 <= weight, value <= 1000'],
  ex: [[L('3 50', '10 60', '20 100', '30 120'), '220', 'Take items 2 and 3: weight 50, value 220.'], [L('2 5', '6 10', '7 20'), '0', 'Nothing fits.']],
  hidden: [L('1 1', '1 1'), L('1 10', '5 7'), L('4 7', '1 1', '3 4', '4 5', '5 7'), L('5 10', '5 10', '4 40', '6 30', '3 50', '3 20'), L('60 1000', ...Array.from({ length: 60 }, (_, i) => { const r = rnd(i + 5000); return `${1 + Math.floor(r() * 120)} ${1 + Math.floor(r() * 500)}`; }))],
  starter: 'def solve(items, W):\n    return 0\n\nn, W = map(int, input().split())\nitems = [tuple(map(int, input().split())) for _ in range(n)]\nprint(solve(items, W))\n',
  hints: ['Let dp[w] be the best value with capacity w.', 'For each item, update dp from high capacity to low so that the item is used at most once.', 'dp[w] = max(dp[w], dp[w - weight] + value) for w from W down to weight.'],
